struct PriceRow: View {
    let title: String
    let price: String
    var body: some View {
        ViewThatFits {                           // first one that fits wins
            HStack { Text(title); Spacer(); Text(price).bold() }
            VStack(alignment: .leading) { Text(title); Text(price).bold() }
        }
    }
}

// Order matters
Text("Hi").padding().background(.yellow)   // yellow includes padding
Text("Hi").background(.yellow).padding()   // yellow only behind text
